// Architecture overview for the same six-word, two-coordinate model used below.
// Coordinates are generated by model.js, not a separate illustrative network.
export const networkScene = {
  chapter: '01 · The prediction task',
  title: 'A small neural network learns the embedding.',
  eq: String.raw`d_c=\operatorname{onehot}(x),\qquad h_c=W_{\mathrm{in}}d_c`,
  caption: 'Skip-gram is a shallow neural network with one hidden layer using a linear activation function and a nonlinear softmax output.',
  detail: '',
  alt: 'A neural network with six one-hot input units, two linear hidden units, and six score units followed by nonlinear softmax. W in has 2 rows and 6 columns; W out has 6 rows and 2 columns. The support input selects hidden coordinates 0.6 and 0.4. Both coordinates contribute to every score, and softmax converts all scores into probabilities.'
};

export function renderNetwork(t, n, helpers) {
  const {m, text, line, rect, group, ease, clamp, fmt, vocab, initial,
    forward, BLUE, RUST, INK, MUTED, RULE} = helpers;
  const result = forward(initial);
  const hiddenProgress = ease(clamp(t / .38));
  const scoreProgress = ease(clamp((t - .28) / .40));
  const probabilityProgress = ease(clamp((t - .64) / .36));
  const inputRadius = n ? 13 : 17;
  const hiddenRadius = n ? 19 : 23;
  const scoreRadius = n ? 16 : 19;
  const inputs = n
    ? Array.from({length: 6}, (_, j) => [120 + 48*j, 63])
    : Array.from({length: 6}, (_, j) => [110, 116 + 41*j]);
  const hidden = n ? [[190, 184], [310, 184]] : [[380, 189], [380, 247]];
  const scores = n
    ? Array.from({length: 6}, (_, j) => [120 + 48*j, 307])
    : Array.from({length: 6}, (_, j) => [645, 116 + 41*j]);
  let s = '';

  const circle = (x, y, r, color, fill = 'white', width = 1.5) =>
    `<circle cx="${x}" cy="${y}" r="${r}" stroke="${color}" stroke-width="${width}" fill="${fill}"/>`;
  // Trim the connections to the circles, keeping the neuron marks unobscured.
  const ends = (a, b, ra, rb) => {
    const dx = b[0]-a[0], dy = b[1]-a[1], length = Math.hypot(dx, dy);
    return [[a[0]+dx*ra/length, a[1]+dy*ra/length],
      [b[0]-dx*rb/length, b[1]-dy*rb/length]];
  };
  const connection = (a, b, ra, rb, color, progress = 0) => {
    const [start, end] = ends(a, b, ra, rb);
    let mark = group(line(...start, ...end, RULE, n ? 1 : 1.2), .75);
    if (progress > 0) {
      const current = [start[0] + (end[0]-start[0])*progress,
        start[1] + (end[1]-start[1])*progress];
      mark += line(...start, ...current, color, n ? 1.8 : 2.2);
      if (progress < 1) mark += circle(...current, n ? 2.5 : 3, color, color, 0);
    }
    return mark;
  };

  // All weight connections remain visible; only the nonzero input contributes.
  for (let j = 0; j < inputs.length; j++) {
    for (const h of hidden) s += connection(inputs[j], h, inputRadius,
      hiddenRadius, BLUE, j === 1 ? hiddenProgress : 0);
  }
  for (const h of hidden) for (const z of scores) {
    s += connection(h, z, hiddenRadius, scoreRadius, RUST, scoreProgress);
  }

  if (n) {
    // Stacked layers preserve readable neuron size on a narrow screen.
    s += m('d_c', 47, 57, 85, 32, 22, BLUE);
    s += text('one-hot', 47, 83, 12, MUTED);
    s += text('support', inputs[1][0], 94, 12, BLUE);
    s += m(String.raw`W_{\mathrm{in}}`, 49, 120, 94, 32, 22, BLUE);
    s += m(String.raw`2\times 6`, 49, 146, 90, 28, 17, BLUE);
    s += m('h_c', 49, 180, 90, 32, 23, BLUE);
    s += text('linear', 49, 205, 12, BLUE);
    s += m(String.raw`\phi(a)=a`, 49, 225, 96, 26, 15, BLUE);
    s += m(String.raw`W_{\mathrm{out}}`, 51, 259, 100, 32, 22, RUST);
    s += m(String.raw`6\times 2`, 49, 284, 90, 28, 17, RUST);
    s += m('z_c', 49, 314, 90, 32, 23, RUST);
    s += text('scores', 49, 337, 12, MUTED);

    // A separate operation consumes the complete score vector.
    for (const z of scores) s += line(z[0], z[1]+scoreRadius,
      250, 355, RULE, 1);
    s += rect(123, 355, 254, 40, INK, 'white', 3, 1.5);
    s += m(String.raw`\operatorname{softmax}`, 199, 375, 142, 32, 20, INK);
    s += text('nonlinear', 311, 380, 12, INK);
    s += line(250, 395, 250, 405, INK, 1.5, true);
    s += m('p', 49, 422, 90, 32, 23, BLUE);
    for (let j = 0; j < result.p.length; j++) {
      const barHeight = result.p[j] / .3 * 28 * probabilityProgress;
      s += rect(inputs[j][0]-8, 433-barHeight, 16, barHeight,
        'none', j === 2 ? RUST : BLUE);
      s += line(inputs[j][0]-11, 434, inputs[j][0]+11, 434, RULE, 1);
    }
    s += text('six probabilities, in vocabulary order', 250, 448, 11, MUTED);
  } else {
    s += m('d_c', 110, 49, 100, 36, 26, BLUE);
    s += text('one-hot input', 110, 79, 14, MUTED);
    s += m(String.raw`W_{\mathrm{in}}`, 248, 49, 180, 36, 27, BLUE);
    s += m(String.raw`k\times |V|=2\times 6`, 248, 79, 210, 32, 18, BLUE);
    s += m('h_c', 380, 49, 100, 36, 27, BLUE);
    s += text('embedding', 380, 79, 14, BLUE);
    s += m(String.raw`W_{\mathrm{out}}`, 510, 49, 185, 36, 27, RUST);
    s += m(String.raw`|V|\times k=6\times 2`, 510, 79, 210, 32, 18, RUST);
    s += m('z_c', 645, 49, 100, 36, 26, RUST);
    s += text('linear scores', 645, 79, 14, MUTED);
    s += m('p', 916, 49, 110, 36, 26, BLUE);
    s += text('probabilities', 916, 79, 14, BLUE);
    for (let j = 0; j < scores.length; j++) {
      s += text(vocab[j], 78, inputs[j][1]+5, 14,
        j === 1 ? BLUE : MUTED, 'end');
      s += line(scores[j][0]+scoreRadius, scores[j][1], 727,
        scores[j][1], RULE, 1.2);
      s += line(833, scores[j][1], 862, scores[j][1], RULE, 1.2);
      s += rect(867, scores[j][1]-8, result.p[j]/.3*100*probabilityProgress,
        16, 'none', j === 2 ? RUST : BLUE);
    }
    s += rect(727, 98, 106, 242, INK, 'white', 3, 1.5);
    s += m(String.raw`\operatorname{softmax}`, 780, 207, 104, 35, 19, INK);
    s += text('nonlinear', 780, 237, 14, INK);
    s += text('hidden layer: linear activation', 380, 365, 17, BLUE);
    s += m(String.raw`\phi(a)=a`, 380, 395, 190, 36, 23, BLUE);
    s += text('both matrices are learned', 678, 395, 15, MUTED);
  }

  // Draw neurons last so every connection terminates cleanly at a unit.
  for (let j = 0; j < inputs.length; j++) {
    const [x, y] = inputs[j], selected = j === 1;
    s += circle(x, y, inputRadius, selected ? BLUE : MUTED,
      selected ? '#edf3f7' : 'white', selected ? 2 : 1.2);
    s += m(selected ? '1' : '0', x, y, 32, 30, n ? 17 : 20,
      selected ? BLUE : MUTED);
  }
  hidden.forEach(([x,y], j) => {
    s += circle(x, y, hiddenRadius, BLUE, '#edf3f7', 2);
    s += group(m(fmt(result.h[j], 1), x, y, 48, 35, n ? 20 : 25, BLUE),
      hiddenProgress);
  });
  scores.forEach(([x,y], j) => {
    s += circle(x, y, scoreRadius, RUST, 'white', 1.5);
    s += group(m(fmt(result.z[j]), x, y, 50, 30, n ? 12 : 14, RUST),
      scoreProgress);
  });
  return s;
}
